import {openHandoffDesk} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/handoff-store.mjs';

export async function openMerchantCasePackages({config,store,environment=process.env}) {
  const support=config.support;let sources,handoffs,operations,primary;
  try {
    sources=await createCaseSourceDelivery({store,
      directory:support.sourceDirectory??join(support.casesDirectory,'source-bundles'),
      python:environment.SCF_PYTHON??'python3',environment});
    handoffs=support.packageSourcesFile?await openHandoffDesk({configPath:support.packageSourcesFile,
      casesDir:support.casesDirectory,environment}):null;
    operations=await openCasePackageOperations({store,casesDirectory:support.casesDirectory,
      directory:support.packagesDirectory??defaultCasePackagesDirectory(support.casesDirectory),
      sourceDelivery:sources,handoffDesk:handoffs,python:environment.SCF_PYTHON??'python3',environment});
  } catch(problem) {
    primary=problem;await Promise.allSettled([operations?.close(),sources?.close(),handoffs?.close()]);throw primary;
  }
  let closed=null;
  return Object.freeze({
    summary:()=>operations.catalog(),
    async call(name,args={}) {
      switch(name) {
        case 'merchant_case_package_catalog': return operations.catalog();
        case 'merchant_case_package_operations': return operations.list(args);
        case 'merchant_case_package_inputs': return operations.listInputs(args);
        case 'merchant_case_package_status': return operations.status(args.id);
        case 'merchant_case_package_prepare': return operations.prepare(args);
        case 'merchant_case_package_run': return operations.run(args.id);
        case 'merchant_case_package_pause': return operations.stop(args.id);
        case 'merchant_case_package_inventory': return operations.inventory(args);
        case 'merchant_case_package_remote_inspect': return operations.inspectRemote(args);
        case 'merchant_case_package_open': return operations.receivedCase(args.id);
        case 'merchant_case_package_file': return operations.readFile(args);
        case 'merchant_case_package_original_file': return operations.readOriginal(args);
        case 'merchant_case_package_file_release': return operations.release(args);
        case 'merchant_case_package_export_manifest': return operations.exportManifest(args.exportId);
        case 'merchant_case_package_export_file': return operations.exportFile(args);
        case 'merchant_case_package_export_file_release':
          await operations.release({source:{kind:'operation',id:args.exportId},readId:args.readId});
          return {exportId:args.exportId,readId:args.readId,released:true};
        default: throw Object.assign(new Error('Unknown original package operation.'),{code:'TOOL_NOT_FOUND'});
      }
    },
    close() {
      if(closed)return closed;
      closed=(async()=>{
        await operations.close();
        const outcomes=await Promise.allSettled([sources.close(),handoffs?.close()]);
        const failures=outcomes.filter(value=>value.status==='rejected');
        if(failures.length)throw new AggregateError(failures.map(value=>value.reason),'Original package owners did not finish closing.');
      })().catch(problem=>{closed=null;throw problem;});
      return closed;
    }
  });
}

// MIT. The original commercial receiving controller under the configured Support owner.
import {openCommercialReceivingController} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/operator.mjs';
import {failure} from './config.mjs';
const ACTIONS={
  merchant_case_commercial_receiving_status:'status',
  merchant_case_commercial_receiving_capture:'capture',
  merchant_case_commercial_receiving_inspect:'inspect',
  merchant_case_commercial_receiving_attach:'attach',
  merchant_case_commercial_receiving_case:'inspect-case',
  merchant_case_commercial_receiving_restore:'restore',
};
export function merchantCommercialReceiving({cases,casesDirectory,environment=process.env}={}){
  let opening,closing=false,closed;
  const original=()=>opening??=Promise.resolve(cases()).then(store=>openCommercialReceivingController({
    store,casesDirectory:casesDirectory(),environment}));
  return {
    handles:name=>Object.hasOwn(ACTIONS,name),
    async call(name,args){
      if(closing)throw failure('SUPPORT_CLOSING','The original Support owner is draining its active operations.');
      if(!Object.hasOwn(ACTIONS,name))throw failure('TOOL_NOT_FOUND','Unknown original quotation receiving operation.');
      return (await original()).call(ACTIONS[name],args);
    },
    close(){
      return closed??=(async()=>{closing=true;if(opening)await(await opening).close();})();
    },
  };
}

// MIT. Full tariff quotation receiving under the original configured Support owner.
import {openCommercialTariffController} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-controller.mjs';
import {failure,exact,privateSupportDirectory} from './config.mjs';
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
const HASH=/^[a-f0-9]{64}$/;
const ACTIONS=Object.fromEntries(['status','catalog','selection','capture','inspect','attach','case','restore']
  .map(action=>['merchant_case_commercial_tariff_'+action,action]));
export function merchantCommercialTariffs({cases,casesDirectory,exportsDirectory,reads}={}){
  let opening,closing=false,closed;
  const original=()=>opening??=Promise.resolve(cases()).then(store=>openCommercialTariffController({store,casesDirectory:casesDirectory()}));
  return {
    handles:name=>Object.hasOwn(ACTIONS,name)||name==='merchant_case_commercial_tariff_file',
    async call(name,args){
      if(closing)throw failure('SUPPORT_CLOSING','The original Support owner is draining current tariff work.');
      if(name==='merchant_case_commercial_tariff_file'){
        exact(args,['id','revision','sourceId','kind','readId','expectedSha256','offset','limit'],['id','revision','sourceId','kind']);
        if(!UUID.test(args.id??'')||!HASH.test(args.revision??'')||!HASH.test(args.sourceId??'')||
            !['SOURCE','PORTFOLIO'].includes(args.kind)||args.readId!==undefined&&!UUID.test(args.readId))
          throw failure('INVALID_PARAMS','Select the exact original case revision, tariff source and complete file.');
        const choice={id:args.id,revision:args.revision,sourceId:args.sourceId,kind:args.kind};
        return {...choice,...await reads.read({scope:'commercial:'+args.id,key:JSON.stringify(choice),kind:'merchant-commercial-tariff',
          directory:await privateSupportDirectory(exportsDirectory()),readId:args.readId,expectedSha256:args.expectedSha256,
          offset:args.offset,limit:args.limit,load:async()=>{
            const received=await(await original()).call('download',choice),result=received.result;
            return {bytes:result.body,name:result.descriptor.filename,type:result.descriptor.mediaType};
          }})};
      }
      if(!Object.hasOwn(ACTIONS,name))throw failure('TOOL_NOT_FOUND','Unknown original tariff quotation operation.');
      return (await original()).call(ACTIONS[name],args);
    },
    close(){return closed??=(async()=>{closing=true;if(opening)await(await opening).close();})();},
  };
}

import {merchantCommercialReceiving} from './support-commercial-receiving.mjs';
import {merchantCommercialTariffs} from './support-commercial-tariffs.mjs';
// MIT. Original saved merchant quotation through the configured support owner.
import {openCaseCommercial,commercialWorkspaceId} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/case-commercial.mjs';
import {failure,exact,privateSupportDirectory} from './config.mjs';
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
const HASH=/^[a-f0-9]{64}$/;
export function merchantCommercial({cases,casesDirectory,exportsDirectory,reads,environment=process.env}) {
  const receiving=merchantCommercialReceiving({cases,casesDirectory,environment});
  const tariffs=merchantCommercialTariffs({cases,casesDirectory,exportsDirectory,reads});
  let model;
  const original=async()=>model??=openCaseCommercial({store:await cases(),workspaceId:commercialWorkspaceId(casesDirectory())});
  const selected=args=>{if(!UUID.test(args.id??''))throw failure('INVALID_CASE_ID','Choose the original saved case UUID.');return 'commercial:'+args.id;};
  return {
    handles:name=>name.startsWith('merchant_case_commercial'),
    async call(name,args) {
      if(tariffs.handles(name))return tariffs.call(name,args);
      if(receiving.handles(name))return receiving.call(name,args);
      const scope=selected(args);
      if(name==='merchant_case_commercial_file_reads') {
        exact(args,['id'],['id']);return {id:args.id,...reads.status(scope)};
      }
      if(name==='merchant_case_commercial_file_release') {
        exact(args,['id','readId'],['id','readId']);
        if(!UUID.test(args.readId??''))throw failure('INVALID_PARAMS','Keep the original file read UUID.');
        await reads.release(scope,args.readId);return {id:args.id,readId:args.readId,released:true};
      }
      if(name==='merchant_case_commercial_file') {
        exact(args,['id','revision','quoteId','quoteSha256','kind','expectedSha256','readId','offset','limit'],
          ['id','revision','quoteId','quoteSha256','kind']);
        if(!HASH.test(args.revision??'')||!UUID.test(args.quoteId??'')||!HASH.test(args.quoteSha256??'')||
            !['QUOTE','QUOTE_JSON'].includes(args.kind)||args.readId!==undefined&&!UUID.test(args.readId))
          throw failure('INVALID_PARAMS','Choose the exact saved case revision, quote edition and document kind.');
        const choice={id:args.id,revision:args.revision,quoteId:args.quoteId,quoteSha256:args.quoteSha256,kind:args.kind};
        return {...choice,...await reads.read({scope,key:JSON.stringify(choice),kind:'merchant-commercial',
          directory:await privateSupportDirectory(exportsDirectory()),readId:args.readId,offset:args.offset,
          limit:args.limit,expectedSha256:args.expectedSha256,load:async()=>{
            const result=await (await original()).download(choice);
            return {bytes:result.body,name:result.descriptor.filename,type:result.descriptor.mediaType};
          }})};
      }
      const method={
        merchant_case_commercial:'read',merchant_case_commercial_preview:'preview',
        merchant_case_commercial_save_draft:'saveDraft',merchant_case_commercial_publish:'publish',
        merchant_case_commercial_receive_pricing:'receivePricing',merchant_case_commercial_receive:'receive',
        merchant_case_commercial_compare:'compare',
        merchant_case_commercial_preview_implementation:'previewImplementation',
        merchant_case_commercial_adopt_implementation:'adoptImplementation',
      }[name];
      if(!method)throw failure('TOOL_NOT_FOUND','Unknown original merchant quotation operation.');
      return (await original())[method](args);
    },
    close:async()=>{const results=await Promise.allSettled([receiving.close(),tariffs.close()]);const failed=results.find(row=>row.status==='rejected');if(failed)throw failed.reason;},
  };
}

// MIT. Original support transfer adapter and native saved-case reopening.
import { createHash, randomUUID } from 'node:crypto';
import { join, resolve } from 'node:path';
import { realpath } from 'node:fs/promises';
import { createRetainedDownload } from './retained-download.mjs';
import { parseSupportExportManifest } from './support.mjs';
import { failure, privateSupportDirectory } from './config.mjs';
import { importRuntimeHandoff, MAX_HANDOFF_BYTES } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/runtime-support.mjs';
import { openCaseStore, caseMetadata } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/case-store.mjs';
export { openMerchantFileClient } from './retained-download.mjs';

const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const decode = bytes => new TextDecoder('utf-8', { fatal: true }).decode(bytes);
const validReadId = value => typeof value === 'string' && /^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(value);
const transfer = createRetainedDownload({ manifestName: 'support-export.json', parseManifest: parseSupportExportManifest,
  maximumBytes: MAX_HANDOFF_BYTES, stateSchema: 'stellar-forge.merchant-support-download.v1',
  resultSchema: 'stellar-forge.merchant-support-download-result.v1', toolPrefix: 'merchant_support_export',
  errorPrefix: 'SUPPORT', clientName: 'starforge-support-download', describe: manifest => ({ case: manifest.case }) });
const { lockedDownload, loadContext, bytesAt, verifiedFile, checkpoint } = transfer;
export const downloadSupportExport = transfer.download;
export const inspectSupportExport = transfer.inspect;

/** Offline continuation through the original SF74 importer and its versioned store. */
export async function reopenDownloadedSupportExport({ directory, casesDirectory } = {}) {
  if (typeof casesDirectory !== 'string' || !casesDirectory || casesDirectory.includes('\0'))
    throw failure('SUPPORT_DOWNLOAD_CONFIGURATION', 'Supply the original private case directory.');
  const cases = await realpath(await privateSupportDirectory(resolve(casesDirectory)));
  return lockedDownload(directory, async context => {
    const bytes = await bytesAt(join(context.root, 'support-export.json'), 65000);
    let exportId; try { exportId = JSON.parse(decode(bytes)).exportId; } catch { throw failure('SUPPORT_EXPORT_INVALID', 'Open a completed original support export.'); }
    await loadContext(context, bytes, exportId);
    for (const file of context.manifest.files) await verifiedFile(join(context.root, file.name), file);
    const source = JSON.parse(decode(await bytesAt(join(context.root, 'case.json'), MAX_HANDOFF_BYTES)));
    let original = { workspaceText: decode(await bytesAt(join(context.root, 'merchant-workspace.json'), MAX_HANDOFF_BYTES)), supportText: null, metadata: caseMetadata(source.metadata) };
    if (context.manifest.case.supportSha256 !== null)
      original = await importRuntimeHandoff(decode(await bytesAt(join(context.root, 'merchant-support.json'), MAX_HANDOFF_BYTES)));
    if (sha(original.workspaceText) !== context.manifest.case.workspaceSha256 ||
        (original.supportText === null ? null : sha(original.supportText)) !== context.manifest.case.supportSha256)
      throw failure('SUPPORT_DOWNLOAD_EXPORT_CHANGED', 'The original case inputs disagree with the downloaded completion manifest.');
    const bound = context.state.localCase;
    if (bound && (bound.directory !== cases || !validReadId(bound.id)))
      throw failure('SUPPORT_DOWNLOAD_CASE_CONFLICT', 'This download already reopens in a different local case directory. Use its retained original case.');
    if (!bound) { context.state.localCase = { directory: cases, id: randomUUID(), revision: null }; await checkpoint(context); }
    const local = context.state.localCase, store = await openCaseStore(cases);
    if (!local.revision) {
      let existing;
      try { existing = await store.read(local.id); } catch (error) { if (error.code !== 'CASE_NOT_FOUND') throw error; }
      if (existing) {
        // A save may have completed before its download checkpoint, followed by
        // a legitimate local edit. Recover the original first revision without
        // replaying the save over the current head or discarding the edit.
        let before = null, initial = null; const seen = new Set();
        do {
          const page = await store.history(local.id, { before, limit: 100 });
          for (const row of page.revisions) {
            if (seen.has(row.revision)) throw failure('SUPPORT_DOWNLOAD_CASE_CONFLICT', 'The retained local case history contains a cycle.');
            seen.add(row.revision);
            if (row.previousRevision === null) initial = row;
          }
          before = page.nextBefore;
        } while (before);
        if (!initial) throw failure('SUPPORT_DOWNLOAD_CASE_CONFLICT', 'The original imported case revision is absent from local history.');
        const first = await store.read(local.id, initial.revision);
        if (sha(first.workspaceText) !== context.manifest.case.workspaceSha256 ||
            (first.supportText === null ? null : sha(first.supportText)) !== context.manifest.case.supportSha256 ||
            JSON.stringify(caseMetadata(first.metadata)) !== JSON.stringify(caseMetadata(original.metadata)))
          throw failure('SUPPORT_DOWNLOAD_CASE_CONFLICT', 'The first local case revision differs from this downloaded original handoff.');
        local.revision = initial.revision;
      } else {
        const saved = await store.save({ id: local.id, expectedRevision: null, ...original, metadata: caseMetadata(original.metadata) });
        local.revision = saved.case.revision;
      }
      await checkpoint(context);
    }
    const reopened = await store.read(local.id);
    return { schema: 'stellar-forge.merchant-support-reopened.v1', exportId, sourceCase: context.manifest.case,
      case: { id: reopened.id, revision: reopened.revision, importedRevision: local.revision, directory: cases },
      manifestSha256: context.manifestSha256, state: 'REOPENED' };
  });
}
